// Cross-runtime text-splitter contract test.
//
// Reads tests/fixtures/text_splitter/contract.json (regenerated by
// scripts/regenerate_text_splitter_fixture.py from
// docs/spec/text-splitter-contract.toml) and asserts that the PRODUCTION
// splitter in src/cpp/sentence_split.hpp (called by
// piper.cpp:splitTextToSentences for streaming synthesis) matches it:
//
//   1. the sentence terminators and closing punctuation equal
//      runtimes.cpp.* in the fixture;
//   2. kNonTerminatingAbbreviations equals
//      canonical.non_terminating_abbreviations (Issue #831);
//   3. every split_cases entry splits to exactly its expected chunks
//      (Issue #831: "3.14", "e.g." and "i.e." do not end a sentence).
//
// The contract is checked in SentenceSplitMode::Multilingual, the mode
// piper.cpp:phonemeTypeToSplitMode picks for MultilingualPhonemes models.
// OpenJTalk mode treats only 。！？ as terminators, so ASCII text is never
// split there and the rule has nothing to act on.
//
// Whitespace: unlike Python/Rust/C#/Go, the C++ splitter does not trim, so
// the space after a terminator stays at the start of the next chunk
// (" World!", see test_split_sentences.cpp). That behaviour is outside
// Issue #831, so the chunks are compared with surrounding ASCII whitespace
// removed -- the same trim the other runtimes apply before returning.
//
// Self-contained: only links gtest + json.hpp, no piper-library dependency.

#include <gtest/gtest.h>

#include <cstdint>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <iterator>
#include <sstream>
#include <string>
#include <vector>

#include "json.hpp"
#include "sentence_split.hpp"

namespace {

namespace fs = std::filesystem;
using nlohmann::json;

// ---------------------------------------------------------------------------
// Fixture loading (mirrors test_short_text_contract.cpp)
// ---------------------------------------------------------------------------

fs::path findFixturePath() {
  if (const char* env = std::getenv("PIPER_PLUS_TEXT_SPLITTER_FIXTURE")) {
    return fs::path(env);
  }

  const fs::path needle =
      fs::path("tests") / "fixtures" / "text_splitter" / "contract.json";
  fs::path cwd = fs::current_path();
  for (int depth = 0; depth < 8; ++depth) {
    fs::path candidate = cwd / needle;
    if (fs::exists(candidate)) {
      return candidate;
    }
    if (!cwd.has_parent_path() || cwd == cwd.parent_path()) {
      break;
    }
    cwd = cwd.parent_path();
  }
  return needle;  // last resort — will fail open + give a useful error
}

json loadFixture() {
  const fs::path fixture_path = findFixturePath();
  std::ifstream stream(fixture_path, std::ios::binary);
  EXPECT_TRUE(stream.is_open())
      << "Cannot open text-splitter contract fixture: " << fixture_path
      << " (cwd=" << fs::current_path()
      << "). Set PIPER_PLUS_TEXT_SPLITTER_FIXTURE if the default search path "
         "doesn't apply.";
  std::stringstream buffer;
  buffer << stream.rdbuf();
  return json::parse(buffer.str());
}

std::string trimAsciiWhitespace(const std::string& s) {
  const char* ws = " \t\n\r\f\v";
  const std::size_t begin = s.find_first_not_of(ws);
  if (begin == std::string::npos) {
    return "";
  }
  const std::size_t end = s.find_last_not_of(ws);
  return s.substr(begin, end - begin + 1);
}

std::vector<std::string> splitTrimmed(const std::string& text,
                                      piper::SentenceSplitMode mode) {
  std::vector<std::string> chunks;
  for (const auto& chunk : piper::splitTextToSentencesIn(text, mode)) {
    chunks.push_back(trimAsciiWhitespace(chunk));
  }
  return chunks;
}

// Every codepoint in the BMP for which `pred` holds, ascending.
template <typename Pred>
std::vector<std::uint32_t> collectCodepoints(Pred pred) {
  std::vector<std::uint32_t> out;
  for (std::uint32_t c = 0; c <= 0xFFFF; ++c) {
    if (pred(static_cast<char32_t>(c))) {
      out.push_back(c);
    }
  }
  return out;
}

}  // namespace

TEST(TextSplitterContract, FixtureHasCppRuntimeAndSplitCases) {
  const auto fixture = loadFixture();
  ASSERT_TRUE(fixture.contains("runtimes"));
  ASSERT_TRUE(fixture["runtimes"].contains("cpp"));
  ASSERT_TRUE(fixture.contains("split_cases"));
  EXPECT_FALSE(fixture["split_cases"].empty());
}

TEST(TextSplitterContract, SentenceTerminatorsMatchFixture) {
  const auto fixture = loadFixture();
  const auto expected = fixture["runtimes"]["cpp"]["sentence_terminators"]
                            .get<std::vector<std::uint32_t>>();
  const auto actual = collectCodepoints([](char32_t c) {
    return piper::isSentenceTerminator(c,
                                       piper::SentenceSplitMode::Multilingual);
  });
  EXPECT_EQ(actual, expected);
}

TEST(TextSplitterContract, ClosingPunctuationMatchesFixture) {
  const auto fixture = loadFixture();
  const auto expected = fixture["runtimes"]["cpp"]["closing_punctuation"]
                            .get<std::vector<std::uint32_t>>();
  const auto actual = collectCodepoints(
      [](char32_t c) { return piper::isClosingPunctuation(c); });
  EXPECT_EQ(actual, expected);
}

TEST(TextSplitterContract, NonTerminatingAbbreviationsMatchFixture) {
  const auto fixture = loadFixture();
  const auto expected = fixture["canonical"]["non_terminating_abbreviations"]
                            .get<std::vector<std::string>>();
  const std::vector<std::string> actual(
      std::begin(piper::kNonTerminatingAbbreviations),
      std::end(piper::kNonTerminatingAbbreviations));
  EXPECT_EQ(actual, expected);
}

// Issue #831: each split_cases input must split to exactly `expected`.
TEST(TextSplitterContract, SplitCasesMatchFixture) {
  const auto fixture = loadFixture();
  for (const auto& tc : fixture["split_cases"]) {
    const auto input = tc["input"].get<std::string>();
    const auto expected = tc["expected"].get<std::vector<std::string>>();
    SCOPED_TRACE("split_cases input: " + input);
    EXPECT_EQ(splitTrimmed(input, piper::SentenceSplitMode::Multilingual),
              expected);
  }
}

// The rule is not tied to a mode: the ASCII branch (unreachable from
// PhonemeType today) also keeps "3.14" and "e.g." whole. Its terminators are
// . ! ? only, so the cases containing 。 do not apply there.
TEST(TextSplitterContract, SplitCasesAsciiOnlyInputsInAsciiMode) {
  const auto fixture = loadFixture();
  std::size_t checked = 0;
  for (const auto& tc : fixture["split_cases"]) {
    const auto input = tc["input"].get<std::string>();
    bool asciiOnly = true;
    for (const unsigned char ch : input) {
      if (ch >= 0x80) {
        asciiOnly = false;
        break;
      }
    }
    if (!asciiOnly) {
      continue;
    }
    ++checked;
    const auto expected = tc["expected"].get<std::vector<std::string>>();
    SCOPED_TRACE("split_cases input: " + input);
    EXPECT_EQ(splitTrimmed(input, piper::SentenceSplitMode::Ascii), expected);
  }
  EXPECT_GT(checked, 0u);
}
